// The data of the site, highlighted at build time:
//
// - `virtual:site/components`: the list of the components of the gallery
//   (`src/data/components.json`, generated by `pnpm data`), and a loader per
//   component, so a page only downloads the code of its own component,
// - `virtual:site/component/<id>`: a component, with its highlighted code,
// - `virtual:site/charts`: the pages of the chart showcase, with their
//   highlighted code,
// - `virtual:site/apps`: the example apps (`/examples`), with their
//   highlighted code,
// - `./file.rs?highlight` (or `.toml`, `.sh`): a snippet next to the page that
//   shows it, as `{ code, html }`.
import { readFileSync } from "node:fs";
import { extname, join } from "node:path";

import { createHighlighter, type Highlighter } from "shiki";
import type { Plugin } from "vite";

const LIST = "virtual:site/components";
const COMPONENT = "virtual:site/component/";
const CHARTS = "virtual:site/charts";
const APPS = "virtual:site/apps";
const HIGHLIGHT = "?highlight";

const LANGS: Record<string, string> = { ".rs": "rust", ".toml": "toml", ".sh": "shellscript" };

interface Data {
  components: {
    id: string;
    title: string;
    description: string;
    source: { file: string; code: string } | null;
    examples: Example[];
  }[];
  charts?: { id: string; title: string; description: string; examples: Example[] }[];
  apps?: { id: string; title: string; description: string; command: string; examples: Example[] }[];
}

interface Example {
  index: number;
  title: string;
  file: string;
  line: number;
  code: string;
}

export function siteData(): Plugin {
  const file = join(import.meta.dirname, "../src/data/components.json");
  let highlighter: Promise<Highlighter> | undefined;

  const highlight = async (code: string, lang: string) => {
    highlighter ??= createHighlighter({
      themes: ["github-light", "github-dark-default"],
      langs: Object.values(LANGS),
    });

    // The markup of rehype-pretty-code, which the styles of ui.shadcn.com
    // (`src/styles/global.css`) expect.
    const html = (await highlighter).codeToHtml(code, {
      lang,
      themes: { light: "github-light", dark: "github-dark-default" },
      defaultColor: false,
      transformers: [
        {
          pre(node) {
            node.properties = {
              "data-language": lang,
              // As the `pre` of mdx-components.tsx: typeset leaves it alone.
              "data-not-typeset": "",
              tabindex: "0",
              class:
                "no-scrollbar min-w-0 overflow-x-auto overflow-y-auto overscroll-x-contain overscroll-y-auto px-4 py-3.5 outline-none",
            };
          },
          code(node) {
            node.properties = { "data-language": lang, style: "display: grid" };
            // The lines are grid rows: no text between them.
            node.children = node.children.filter((child) => child.type !== "text");
          },
          line(node) {
            node.properties = { "data-line": "" };
            // An empty line keeps the height of a line, as rehype-pretty-code does.
            if (node.children.length === 0) node.children.push({ type: "text", value: " " });
          },
        },
      ],
    });

    return { code, html, lang };
  };

  const read = (): Data => JSON.parse(readFileSync(file, "utf8"));

  const highlightExample = async (e: Example) => ({
    ...e,
    ...(await highlight(e.code, "rust")),
    // The first lines, shown until the code is expanded.
    preview: (await highlight(e.code.split("\n").slice(0, 3).join("\n"), "rust")).html,
  });

  return {
    name: "site-data",
    enforce: "pre",

    resolveId(id) {
      if (id === LIST || id === CHARTS || id === APPS || id.startsWith(COMPONENT)) return `\0${id}`;
    },

    async load(id) {
      if (id === `\0${LIST}`) {
        this.addWatchFile(file);
        const components = read()
          .components.map((c) => ({
            id: c.id,
            title: c.title,
            description: c.description,
            examples: c.examples.map((e) => ({ index: e.index, title: e.title })),
          }))
          .toSorted((a, b) => a.title.localeCompare(b.title));

        const loaders = components
          .map((c) => `  ${JSON.stringify(c.id)}: () => import(${JSON.stringify(COMPONENT + c.id)}),`)
          .join("\n");

        return `export const components = ${JSON.stringify(components)};\nexport const loaders = {\n${loaders}\n};\n`;
      }

      if (id.startsWith(`\0${COMPONENT}`)) {
        this.addWatchFile(file);
        const name = id.slice(COMPONENT.length + 1);
        const component = read().components.find((c) => c.id === name);
        if (!component) return "export default null;";

        const module = component.id.replaceAll("-", "_");
        const result = {
          id: component.id,
          title: component.title,
          description: component.description,
          install: {
            cli: await highlight(`cargo shadcn-iced add ${component.id}`, "shellscript"),
            library: await highlight(
              `use shadcn_iced::${module}::*;\n// or everything at once:\nuse shadcn_iced::prelude::*;`,
              "rust",
            ),
          },
          source: component.source && {
            file: component.source.file,
            ...(await highlight(component.source.code, "rust")),
          },
          examples: await Promise.all(component.examples.map(highlightExample)),
        };

        return `export default ${JSON.stringify(result)};`;
      }

      if (id === `\0${CHARTS}`) {
        this.addWatchFile(file);
        const charts = await Promise.all(
          (read().charts ?? []).map(async (page) => ({
            ...page,
            examples: await Promise.all(page.examples.map(highlightExample)),
          })),
        );

        return `export const charts = ${JSON.stringify(charts)};`;
      }

      if (id === `\0${APPS}`) {
        this.addWatchFile(file);
        const apps = await Promise.all(
          (read().apps ?? []).map(async (app) => ({
            ...app,
            command: await highlight(app.command, "shellscript"),
            examples: await Promise.all(app.examples.map(highlightExample)),
          })),
        );

        return `export const apps = ${JSON.stringify(apps)};`;
      }

      if (id.endsWith(HIGHLIGHT)) {
        const path = id.slice(0, -HIGHLIGHT.length);
        const lang = LANGS[extname(path)];
        if (!lang) this.error(`No language for ${path}`);

        this.addWatchFile(path);
        const code = readFileSync(path, "utf8").replace(/\r\n/g, "\n").trimEnd();
        return `export default ${JSON.stringify(await highlight(code, lang))};`;
      }
    },
  };
}
